script:
(function () {
  'use strict';
  // Immediate annuity income from a lump-sum premium A, f payments a year for N years (n = f x N).
  // Payout-rate method: yearly income = A x payout rate; each payment = yearly income / f.
  //   Implied return: the periodic rate p solving A = PMT x (1 - (1 + p)^-n) / p (x (1 + p) when
  //   the first payment is immediate), found by bisection and shown as the yearly rate (1 + p)^f - 1.
  // Interest method: the annual rate i is an effective yearly rate, so p = (1 + i)^(1/f) - 1;
  //   PMT = A x p / (1 - (1 + p)^-n), divided by (1 + p) when payments start straight away;
  //   PMT = A / n at 0%.
  // CHECKS (Node, scratch tests): $100,000 at 6% for 20 years, yearly payments in arrears = $8,718.46
  // (standard annuity formula, 0.06 / (1 - 1.06^-20)); in advance = $8,224.96; monthly at 6% a year
  // effective (p = 1.06^(1/12) - 1) matches the same formula; 0% over 10 years yearly =
  // $10,000; feeding the interest-method payment into the payout method returns the same 6.00%
  // implied rate; a 5% payout over 20 years yearly gives back exactly the premium, so 0.00%;
  // payback years = premium / yearly income (7% payout -> 14.3 years).
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var cents = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var one = new Intl.NumberFormat('en-US', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var FREQ = { 12: 'Monthly', 4: 'Quarterly', 2: 'Twice-yearly', 1: 'Yearly' };

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  // Present value of n level payments of 1 at periodic rate p; due = paid at the start of each period.
  function pvFactor(p, n, due) {
    if (Math.abs(p) < 1e-12) return n;
    var a = (1 - Math.pow(1 + p, -n)) / p;
    return due ? a * (1 + p) : a;
  }

  // Yearly rate equivalent to periodic rate p (tiny values shown as 0).
  function yearly(p, f) {
    var y = Math.pow(1 + p, f) - 1;
    return Math.abs(y) < 0.00005 ? 0 : y;
  }

  // Periodic rate that makes n payments of pmt worth A today.
  function solveRate(A, pmt, n, due) {
    var f = function (p) { return pmt * pvFactor(p, n, due) - A; };
    var lo = -0.99, hi = 1;
    if (f(lo) < 0 || f(hi) > 0) return null;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (f(mid) > 0) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }

  function update() {
    var A = num('iaPremium'), method = document.getElementById('iaMethod').value, payout = num('iaPayoutRate'),
        rate = num('iaRate'), N = num('iaYears'), f = parseInt(document.getElementById('iaFreq').value, 10),
        due = document.getElementById('iaTiming').value === 'start';
    var isPayout = method === 'payout';
    document.getElementById('iaWrapPayout').hidden = !isPayout;
    document.getElementById('iaWrapInterest').hidden = isPayout;
    set('iaYearsLabel', isPayout ? 'Years you expect to receive income' : 'Years of payments');
    set('iaYearsHint', isPayout ? 'For a lifetime annuity, use your life expectancy or the age you want to plan to.'
                                : 'A period-certain annuity pays for exactly this many years.');
    var error = document.getElementById('iaError');
    var bad = isNaN(A) || isNaN(N) || A <= 0 || N < 1 || N > 60 || N !== Math.floor(N) ||
              (isPayout ? isNaN(payout) || payout <= 0 || payout > 50 : isNaN(rate) || rate < 0 || rate > 30);
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a premium above $0, ' + (isPayout ? 'a payout rate above 0 and up to 50%' : 'an interest rate from 0 to 30%') +
        ' and 1 to 60 whole years.';
      return;
    }
    var n = N * f, pmt, implied;
    if (isPayout) {
      pmt = A * payout / 100 / f;
      implied = solveRate(A, pmt, n, due);
    } else {
      var p = Math.pow(1 + rate / 100, 1 / f) - 1;
      pmt = A / pvFactor(p, n, due);
      implied = p;
    }
    var annual = pmt * f, total = annual * N;
    set('iaPaymentLabel', FREQ[f] + ' income');
    set('iaPayment', cents.format(pmt));
    set('iaAnnual', money.format(annual));
    set('iaTotalLabel', 'Total income over ' + N + (N === 1 ? ' year' : ' years'));
    set('iaTotal', money.format(total));
    var payback = A / annual;
    set('iaBreakeven', payback > N && !isPayout ? 'Not within the term' : one.format(payback) + ' years');
    set('iaRateTerm', isPayout ? 'Return implied by this income' : 'Payout rate (yearly income ÷ premium)');
    set('iaRateOut', isPayout ? (implied === null ? '–' : pct.format(yearly(implied, f))) : pct.format(annual / A));
    set('iaGain', money.format(total - A));
    var summary;
    if (isPayout) summary = 'If you receive income for ' + N + (N === 1 ? ' year' : ' years') + ', you get back ' + money.format(total) + ' for a ' + money.format(A) +
      ' premium' + (implied === null ? '.' : ', like earning ' + pct.format(yearly(implied, f)) + ' a year on your money.') +
      ' Payments from a life annuity stop when you die, so living longer raises your return and dying sooner lowers it.';
    else summary = 'A ' + money.format(A) + ' premium paid out over ' + N + ' years at ' + rate + '% gives ' + cents.format(pmt) + ' ' +
      FREQ[f].toLowerCase() + ', with nothing left at the end of the period.';
    set('iaSummary', summary);

    var rows = [], cum = 0;
    for (var y = 1; y <= N; y++) {
      cum += annual;
      rows.push('<tr><td>' + y + '</td><td>' + money.format(annual) + '</td><td>' + money.format(cum) + '</td><td>' +
                money.format(Math.max(0, A - cum)) + '</td></tr>');
    }
    document.getElementById('iaSchedule').innerHTML = rows.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('iaForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
